  'demo.bar.tag': 'デモ',
  'demo.bar.opening': 'Curahold のデモを開いています',
  'demo.bar.step.db': 'このタブで Postgres を起動しています。データがブラウザーの外に出ることはありません。',
  'demo.bar.step.schema': 'テーブルとアクセスルールを作成しています。',
