  'demo.bar.reset': '最初からやり直す',
  'demo.bar.customer': '顧客 · {company} のポータル',
  'demo.idea.1': 'N を押して「Acme と更新の打ち合わせ friday @山本 #ヴェルト !high」と入力すると、日付・担当者・顧客・優先度が自動で入ります。複数行を貼り付けると、1 行ずつ別のタスクになります。',
  'demo.idea.2': '「自分のタスク」でタスクの前の丸をクリックすると完了です。下に出る通知から元に戻せます。',
  'demo.idea.3': '顧客 → すべての顧客：「カード」ビューで、どの顧客にどんな理由で対応が必要かがわかります。「更新」「製品」ビューもどうぞ。',
  'demo.idea.4': '顧客 → 商談：商談を別のステージへドラッグするか「受注」にドロップすると、上部の予測がすぐに変わります。',
  'demo.idea.5': 'インサイト → レポート：「新しいレポート」で自分のレポートを作るか、用意されたレポートを開いて変更します。インサイト → ダッシュボード：「追加」で用意されたダッシュボードをホームに置けます。',
  'demo.idea.6': 'インサイト → チーム：誰が何を抱えているか、何が遅れているか、一人ひとりとの 1on1 用ビュー。作業 → タイムラインでこの先の数週間が見えます。',
  'demo.idea.7': '顧客 → ビジネスレビュー：レビューが遅れている顧客、近づいている顧客。「完了」で記録すると次の日付が進みます。サイクルは 設定 → 目標とサイクル で決めます。',
  'demo.idea.8': '「CS — 全般」ボードでタスクを開いてみましょう：フォロー、タスクをリンク（「待機」）、費やした時間、チェックリスト、いちばん下に履歴。ボードではフィルターとビューもお試しください。',
  "demo.idea.9": "顧客のページで「プレイブックを適用」を押すと、オンボーディングのタスクがワンクリックで入ります。",
  'demo.idea.10': 'タスクか顧客を削除して、下の通知で「元に戻す」を選ぶか、メニューからごみ箱を開きます。削除したものは 30 日間残り、配下のすべてと一緒に戻ります。',
  'demo.idea.11': '左下の CuraAI：自分の言葉で質問してください（例：「顧客をインポートするには？」）。答えはドキュメントから、出典付きで返ってきます。',
  'demo.idea.12': '設定 → CRM とスプレッドシート：CRM を接続します。架空データ入りの模擬 CRM で、許可、取り込む内容の選択、項目の対応付け、初回同期の開始という実際の手順をたどれます。',
  'demo.idea.13': '顧客を開いて（たとえばヴェルト・モビリティ）、タイムラインに通話を記録し、ヘルススコアの横の「理由」を見てみましょう。',
  'demo.idea.14': '設定 → ヘルススコア：重みを変えると、プレビューに各顧客のスコアがすぐ表示されます。',
  'demo.idea.15': 'Ctrl K（Mac では ⌘ K）で、顧客・タスク・メンバー・設定を何でも探せます。',
  'demo.idea.16': 'ボードでタスクを複数選んでまとめて変更し、元に戻してみましょう。',
  'demo.idea.17': '設定 → ロールと権限：「…の視点で見る」で、メンバーの目に映る画面を確認できます。',
  'demo.idea.18': '上で山本 結衣か伊藤 早紀に切り替えて、同じ画面で何が変わるかを見てみましょう。',
  'demo.idea.19': '上で松本 千尋（顧客）に切り替えると、クイルフィールドのポータルでは共有されたものだけが見えます。リクエストを出して返信し、次に山本として「CS — 全般」ボードでそれを開き「顧客への返信」を選びます。',
  'demo.idea.20': '左下のメニュー：ダークモードは「外観」、ほかに「言語」と「キーボードショートカット」（? キーでも開けます）。',
