  'fin.steps.zohobooks': "Zoho Books の組織を見られる Zoho アカウントでログインします。\nCurahold に連絡先、請求書、入金の読み取りを許可します。求めるのは読み取り権限だけです。\nここに戻ったら最初の読み込みを始め、照合できなかった顧客を確認します。",
  'fin.steps.xero': "Xero にログインし、連携する組織を選びます。\n連絡先と取引の読み取りを許可します。Curahold は Xero の内容を変更できません。\nここに戻ったら最初の読み込みを始め、照合できなかった顧客を確認します。",
