  'fin.steps.quickbooks': "Intuit にログインし、連携する QuickBooks の会社を選びます。\n会計データへのアクセスを許可します。Curahold が読むのは顧客、請求書、入金だけです。\nここに戻ったら最初の読み込みを始め、照合できなかった顧客を確認します。",
  'fin.steps.odoo': "Odoo でプロフィール → 個人設定 → アカウントセキュリティを開き、API キーを作成します。\nOdoo のアドレスとログイン名を控えます。Odoo.sh や自社サーバーならデータベース名も。\n下に入力します。Odoo Online では API の利用に Custom プランが必要です（Odoo の規定）。",
  'fin.steps.parasut': "Paraşüt のサポートに会社の API 利用を申し込みます。client ID と client secret が届きます。\n会社番号はアドレスバーの uygulama.parasut.com/ の後ろの数字です。\nParaşüt ユーザーのメールアドレスとパスワードと一緒に入力します。パスワードはキーを得るために一度だけ使い、保存しません。",
