  'demo.tour.handover.blurb': "営業が受注し、顧客を担当するチームが同じページで引き継ぎます。途中で何も失われません。",
  'demo.tour.handover.1.title': "ステージ別の商談",
  'demo.tour.handover.1.body': "各列がステージです。成約したら商談を「受注」へドラッグします。",
  'demo.tour.handover.2.title': "商談は経緯ごと引き継がれる",
  'demo.tour.handover.2.body': "関わった人、約束したこと、更新時期が商談に残り、次の担当者に渡ります。",
  'demo.tour.handover.3.title': "カスタマーチームの画面",
  'demo.tour.handover.3.body': "受注した瞬間から顧客はここに。担当者、ヘルス、次の約束が 1 枚のカードに。",
  'demo.tour.handover-loop.title': "受注から「あなたのために作りました」まで",
  'demo.tour.handover-loop.blurb': "営業が受注したときの引き継ぎカード、プロダクトの作業にひも付く要望、そしてリリース時に顧客へ送るメッセージ。",
  'demo.tour.handover-loop.1.title': "営業がいま受注しました",
  'demo.tour.handover-loop.1.body': "Cedarmoor Health が営業パイプラインで 2 年間の更新に署名しました。顧客を開きましょう。",
  'demo.tour.handover-loop.2.title': "カード 1 枚で、何も漏れない",
  'demo.tour.handover-loop.2.body': "関係者とそのスタンス、営業がした約束、プロダクトにまだ待っていること、各種の日付、営業スレッドの最新内容。誰かがまとめを書く必要はありません。",
  'demo.tour.handover-loop.3.title': "確定すれば、担当者が決まる",
  "demo.tour.handover-loop.3.body": "カスタマーサクセス（会社にオンボーディングがあればそちら）で誰が引き継ぐか、どのプレイブックを始めるかを選びます。カード上のどこからでも Ctrl+Enter で確定できます。",
  'demo.tour.handover-loop.4.title': "要望を出している顧客",
  'demo.tour.handover-loop.4.body': "Quillfield Retail はプロダクトに 2 つの要望を出しています。開いてみましょう。",
  'demo.tour.handover-loop.5.title': "待っていること",
  "demo.tour.handover-loop.5.body": "約束と、依頼したプロダクトの作業：ステータス、スプリント終了日、部門。顧客を見られる人なら誰でも、プロダクトのボードを開かずに確認できます。",
  'demo.tour.handover-loop.6.title': "リリースしたら伝える",
  'demo.tour.handover-loop.6.body': "作業が完了すると、担当者にタスクとこのメッセージの下書きが届きました。メールにコピーするか、ポータルの依頼を閉じます。自動では何も送信されません。",
  'demo.tour.handover-loop.7.title': "次の要望をひも付ける",
  'demo.tour.handover-loop.7.body': "プロダクトの作業を検索し、2 回のキー操作で要望をひも付けます。プロダクトのバックログには、待っている顧客の数、その価値、更新が最も近い顧客が表示されます。",
  'demo.tour.move-in.title': "自分のファイルを持ち込む",
  'demo.tour.move-in.blurb': "今使っているツールのエクスポートをドロップして、自分の作業を Curahold で見てみましょう。デモではファイルがデバイスの外に出ません。",
  'demo.tour.move-in.1.title': "どんなエクスポートもここへ",
  'demo.tour.move-in.1.body': "CSV、Excel シート、ボードの JSON エクスポートをここにドロップ。列名から顧客かタスクかを判断します。",
  'demo.tour.move-in.2.title': "ファイルは手元に残る",
  'demo.tour.move-in.2.body': "デモはすべてこのタブ内で動きます。何もアップロードされず、再読み込みで消えます。",
  'demo.tour.move-in.3.title': "保存する前に確認",
  'demo.tour.move-in.3.body': "サブタスク、コメント、独自項目、「待機」リンクも移ります。予行演習で取り込まれるもの・取り込まれないものがわかり、40 のリストが数個の部門ボードにまとまります。",
  'demo.tour.team-load.title': "誰に余裕があり、どの顧客が待っているか",
  'demo.tour.team-load.blurb': "この先の週を一人ずつ、そして各顧客の未完了作業・依頼・チケットを 1 ページで。",
  'demo.tour.team-load.1.title': "この先の週",
